import { AdminPage } from "@/components/admin-page";

export default function Page() {
  return <AdminPage />;
}

"use client";

import { ArrowLeftIcon, ChevronRightIcon, FilterIcon } from "lucide-react";
import { useState } from "react";
import {
  ROLES,
  type RoleFilter,
  roleLabel,
  SORT_OPTIONS,
  type SortOptionId,
  type SortState,
  STATUSES,
  type StatusFilter,
  sortLabel,
  statusLabel,
  toSortOptionId,
} from "@/components/admin-filters";
import { statusLabels } from "@/components/mock-admin";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Drawer,
  DrawerContent,
  DrawerFooter,
  DrawerHeader,
  DrawerTitle,
  DrawerTrigger,
} from "@/components/ui/drawer";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import {
  Stepper,
  StepperContent,
  StepperStep,
  useStepper,
} from "@/components/ui/stepper";

interface AdminFiltersDrawerProps {
  activeCount: number;
  onClearAll: () => void;
  onRoleFilterChange: (role: RoleFilter) => void;
  onSortChange: (id: SortOptionId) => void;
  onStatusFilterChange: (status: StatusFilter) => void;
  roleFilter: RoleFilter;
  sort: SortState | null;
  statusFilter: StatusFilter;
}

/**
 * The mobile half of the users toolbar.
 *
 * A bottom sheet whose body is a `Stepper`: a menu of "label + current value"
 * rows that drill into one screen per filter. Same shape as `tickets-01`'s
 * drawer, because the pattern is the block-level answer to a toolbar that
 * cannot fit — not something each block should reinvent.
 *
 * No `swipeDirection` is passed: the primitive's default is `down`, which is
 * what supplies the bottom-sheet geometry and the drag handle.
 *
 * Filters apply live, with no draft state — `Apply` only dismisses. That is
 * `tickets-01`'s behaviour too, and it is the right one here: the table is
 * visible behind the sheet on larger phones, so a pick shows its effect
 * immediately.
 */
export function AdminFiltersDrawer({
  activeCount,
  onClearAll,
  onRoleFilterChange,
  onSortChange,
  onStatusFilterChange,
  roleFilter,
  sort,
  statusFilter,
}: AdminFiltersDrawerProps) {
  const [open, setOpen] = useState(false);
  const [step, setStep] = useState(0);

  return (
    <Drawer
      onOpenChange={(isOpen) => {
        setOpen(isOpen);
        if (!isOpen) {
          setStep(0);
        }
      }}
      open={open}
    >
      {/* The count is on the trigger because the desktop `Clear N` button is
          hidden at this width -- without it, a filtered table on a phone gives
          no sign that anything is filtering it. */}
      <DrawerTrigger render={<Button variant="outline" />}>
        <FilterIcon className="size-4" />
        Filters
        {activeCount > 0 && <Badge variant="secondary">{activeCount}</Badge>}
      </DrawerTrigger>
      <DrawerContent>
        <div className="mx-auto w-full max-w-sm">
          <Stepper onValueChange={setStep} value={step}>
            <StepperContent>
              <StepperStep>
                <DrawerHeader>
                  <DrawerTitle className="text-center">Filters</DrawerTitle>
                </DrawerHeader>
                <FilterMenu
                  roleValue={roleLabel(roleFilter)}
                  sortValue={sortLabel(sort)}
                  statusValue={statusLabel(statusFilter)}
                />
                <DrawerFooter>
                  {activeCount > 0 && (
                    <Button
                      className="w-full"
                      onClick={onClearAll}
                      variant="ghost"
                    >
                      Clear all
                    </Button>
                  )}
                  <Button className="w-full" onClick={() => setOpen(false)}>
                    Apply
                  </Button>
                </DrawerFooter>
              </StepperStep>

              <StepperStep>
                <SubHeader title="Role" />
                <div className="pb-4">
                  <RadioGroup
                    className="gap-0 divide-y divide-border-muted"
                    onValueChange={(value) => {
                      if (value) {
                        onRoleFilterChange(value as RoleFilter);
                      }
                    }}
                    value={roleFilter}
                  >
                    <FilterOption label="All roles" value="all" />
                    {ROLES.map((role) => (
                      <FilterOption key={role} label={role} value={role} />
                    ))}
                  </RadioGroup>
                </div>
              </StepperStep>

              <StepperStep>
                <SubHeader title="Status" />
                <div className="pb-4">
                  <RadioGroup
                    className="gap-0 divide-y divide-border-muted"
                    onValueChange={(value) => {
                      if (value) {
                        onStatusFilterChange(value as StatusFilter);
                      }
                    }}
                    value={statusFilter}
                  >
                    <FilterOption label="All statuses" value="all" />
                    {STATUSES.map((status) => (
                      <FilterOption
                        key={status}
                        label={statusLabels[status]}
                        value={status}
                      />
                    ))}
                  </RadioGroup>
                </div>
              </StepperStep>

              <StepperStep>
                <SubHeader title="Sort" />
                <div className="pb-4">
                  <RadioGroup
                    className="gap-0 divide-y divide-border-muted"
                    onValueChange={(value) => {
                      if (value) {
                        onSortChange(value as SortOptionId);
                      }
                    }}
                    value={toSortOptionId(sort)}
                  >
                    {SORT_OPTIONS.map((option) => (
                      <FilterOption
                        key={option.id}
                        label={option.label}
                        value={option.id}
                      />
                    ))}
                  </RadioGroup>
                </div>
              </StepperStep>
            </StepperContent>
          </Stepper>
        </div>
      </DrawerContent>
    </Drawer>
  );
}

function FilterOption({ label, value }: { label: string; value: string }) {
  return (
    // biome-ignore lint/a11y/noLabelWithoutControl: control is inside label
    <label className="flex h-12 cursor-pointer items-center gap-3 px-4">
      <RadioGroupItem value={value} />
      <span className="text-sm">{label}</span>
    </label>
  );
}

function FilterMenu({
  roleValue,
  sortValue,
  statusValue,
}: {
  roleValue: string;
  sortValue: string;
  statusValue: string;
}) {
  const { goTo } = useStepper();
  const items = [
    { label: "Role", step: 1, value: roleValue },
    { label: "Status", step: 2, value: statusValue },
    { label: "Sort", step: 3, value: sortValue },
  ];

  return (
    <div className="divide-y divide-border-muted">
      {items.map((item) => (
        <button
          className="flex h-12 w-full cursor-pointer items-center justify-between gap-3 px-4 text-left active:text-muted-foreground"
          key={item.step}
          onClick={() => goTo(item.step)}
          type="button"
        >
          <span className="font-medium text-sm">{item.label}</span>
          <span className="ml-auto inline-flex min-w-0 items-center gap-2 text-muted-foreground text-sm">
            <span className="truncate">{item.value}</span>
            <ChevronRightIcon className="size-4 shrink-0" />
          </span>
        </button>
      ))}
    </div>
  );
}

function SubHeader({ title }: { title: string }) {
  const { goTo } = useStepper();
  return (
    <DrawerHeader>
      <div className="flex items-center gap-2">
        <Button
          aria-label="Back"
          className="-ml-1"
          onClick={() => goTo(0)}
          size="icon-xs"
          variant="ghost"
        >
          <ArrowLeftIcon className="size-4" />
        </Button>
        <DrawerTitle>{title}</DrawerTitle>
      </div>
    </DrawerHeader>
  );
}

import { type Role, type Status, statusLabels } from "@/components/mock-admin";

/**
 * The filter and sort vocabulary, owned in one place.
 *
 * The toolbar, the mobile drawer and the page all need the same option lists
 * and labels. `tickets-01` declares its lists twice — inline in the toolbar and
 * again in the drawer — which works until someone adds an option to one of
 * them. One owner, imported three ways, avoids that.
 *
 * Sort types live here too rather than in `admin-users-table.tsx`, so the
 * dependency runs one way: table and toolbar both import this, and this imports
 * neither.
 */

export type RoleFilter = "all" | Role;
export type StatusFilter = "all" | Status;

export type UserSortKey = "id" | "lastActive" | "name" | "role" | "seats";
export type SortDirection = "asc" | "desc";

export interface SortState {
  direction: SortDirection;
  key: UserSortKey;
}

/** "all" is rendered separately above the separator, so it is not in here. */
export const ROLES: readonly Role[] = ["Admin", "Billing", "Member", "Viewer"];
export const STATUSES: readonly Status[] = ["active", "invited", "suspended"];

export function roleLabel(role: RoleFilter): string {
  return role === "all" ? "All roles" : role;
}

/** Shared by the table's Status cell and the detail view, so they cannot drift. */
export const STATUS_VARIANT: Record<
  Status,
  "default" | "outline" | "secondary"
> = {
  active: "secondary",
  invited: "outline",
  suspended: "outline",
};

export function statusLabel(status: StatusFilter): string {
  return status === "all" ? "All statuses" : statusLabels[status];
}

// ---------------------------------------------------------------------------
// Sort
// ---------------------------------------------------------------------------

/**
 * A sort state flattened to a single string, so one `RadioGroup` can drive it.
 *
 * The toolbar and the table headers write the *same* `sort` state — picking
 * "Name Z–A" moves the header arrow, and clicking a header updates the
 * toolbar's label, with no syncing code. That only holds if every state the
 * headers can reach is nameable here, so all eight key × direction pairs are
 * listed even though a few are unlikely to be picked from the menu. A state the
 * headers could produce but the toolbar could not name would leave the radio
 * group with nothing selected.
 */
export type SortOptionId = "none" | `${UserSortKey}:${SortDirection}`;

export const SORT_OPTIONS: readonly { id: SortOptionId; label: string }[] = [
  { id: "none", label: "Unsorted" },
  { id: "id:asc", label: "ID, first added" },
  { id: "id:desc", label: "ID, last added" },
  { id: "name:asc", label: "Name A–Z" },
  { id: "name:desc", label: "Name Z–A" },
  { id: "role:asc", label: "Role A–Z" },
  { id: "role:desc", label: "Role Z–A" },
  { id: "seats:desc", label: "Seats, most first" },
  { id: "seats:asc", label: "Seats, fewest first" },
  { id: "lastActive:desc", label: "Last active, newest" },
  { id: "lastActive:asc", label: "Last active, oldest" },
];

export function toSortOptionId(sort: SortState | null): SortOptionId {
  return sort ? `${sort.key}:${sort.direction}` : "none";
}

export function fromSortOptionId(id: SortOptionId): SortState | null {
  if (id === "none") {
    return null;
  }
  const [key, direction] = id.split(":");
  return { direction: direction as SortDirection, key: key as UserSortKey };
}

export function sortLabel(sort: SortState | null): string {
  const id = toSortOptionId(sort);
  return SORT_OPTIONS.find((option) => option.id === id)?.label ?? "Unsorted";
}

"use client";

import { ExternalLinkIcon } from "lucide-react";
import { AdminPaymentsToolbar } from "@/components/admin-payments-toolbar";
import {
  PAYMENT_STATUS_VARIANT,
  type Payment,
  paymentStatusLabels,
  paymentTypeLabels,
  truncateId,
} from "@/components/mock-payments";
import type {
  PaymentFilters,
  SortOptionId,
  SortState,
} from "@/components/payment-filters";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { CopyButton } from "@/components/ui/copy-button";
import {
  Table,
  TableBody,
  TableCell,
  TableEmpty,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { TablePagination } from "@/components/ui/table-pagination";

interface AdminPaymentsTableProps {
  filters: PaymentFilters;
  onFiltersChange: (patch: Partial<PaymentFilters>) => void;
  onFiltersClear: () => void;
  onOpenPayment: (id: string) => void;
  onPageIndexChange: (index: number) => void;
  onPageSizeChange: (size: number) => void;
  onSortChange: (id: SortOptionId) => void;
  pageCount: number;
  pageIndex: number;
  pageSize: number;
  rows: readonly Payment[];
  sort: SortState;
  totalCount: number;
}

export function AdminPaymentsTable({
  filters,
  onFiltersChange,
  onFiltersClear,
  onOpenPayment,
  onPageIndexChange,
  onPageSizeChange,
  onSortChange,
  pageCount,
  pageIndex,
  pageSize,
  rows,
  sort,
  totalCount,
}: AdminPaymentsTableProps) {
  return (
    <Card variant="outline">
      <CardHeader>
        <CardTitle>Payments</CardTitle>
      </CardHeader>

      <CardContent className="flex flex-col gap-4">
        <AdminPaymentsToolbar
          filters={filters}
          onChange={onFiltersChange}
          onClear={onFiltersClear}
          onSortChange={onSortChange}
          sort={sort}
        />

        <Table hoverable>
          <TableHeader>
            <TableRow>
              <TableHead className="w-[136px]">Payment ID</TableHead>
              <TableHead>Player</TableHead>
              <TableHead numeric>Amount</TableHead>
              <TableHead>Currency</TableHead>
              <TableHead>Type</TableHead>
              <TableHead>Status</TableHead>
              <TableHead>Created</TableHead>
              <TableHead>Finished</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {rows.length === 0 ? (
              <TableEmpty colSpan={8}>
                No payments match these filters.
              </TableEmpty>
            ) : (
              rows.map((row) => (
                <TableRow className="group/row" key={row.id}>
                  <TableCell>
                    <div className="flex items-center gap-1">
                      {/* Middle-truncated: the head and tail are what someone
                          eyeballs against another system, and the full value is
                          one click away on the clipboard or the record. */}
                      <button
                        className="cursor-pointer rounded-sm font-mono text-xs hover:underline focus-visible:outline-2 focus-visible:outline-ring/50 focus-visible:outline-offset-2"
                        onClick={() => onOpenPayment(row.id)}
                        type="button"
                      >
                        {truncateId(row.id)}
                      </button>
                      <CopyButton size="icon-xs" value={row.id} />
                    </div>
                  </TableCell>
                  <TableCell>
                    <div className="flex items-center justify-between gap-2">
                      <span className="truncate">{row.playerEmail}</span>
                      <Button
                        aria-label={`Open payment ${truncateId(row.id)}`}
                        className="shrink-0 opacity-0 transition-opacity focus-visible:opacity-100 group-hover/row:opacity-100"
                        onClick={() => onOpenPayment(row.id)}
                        size="sm"
                        variant="outline"
                      >
                        <ExternalLinkIcon className="size-3.5" />
                        Open
                      </Button>
                    </div>
                  </TableCell>
                  <TableCell numeric>
                    <span className="font-mono text-xs">{row.amount}</span>
                  </TableCell>
                  <TableCell>
                    <Badge variant="outline">{row.currency}</Badge>
                  </TableCell>
                  <TableCell>
                    <Badge variant="outline">
                      {paymentTypeLabels[row.type]}
                    </Badge>
                  </TableCell>
                  <TableCell>
                    <Badge variant={PAYMENT_STATUS_VARIANT[row.status]}>
                      {paymentStatusLabels[row.status]}
                    </Badge>
                  </TableCell>
                  <TableCell className="whitespace-nowrap text-muted-foreground text-xs">
                    {row.createdAt}
                  </TableCell>
                  <TableCell className="whitespace-nowrap text-muted-foreground text-xs">
                    {row.finishedAt ?? "-"}
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>

        <TablePagination
          onPageIndexChange={onPageIndexChange}
          onPageSizeChange={onPageSizeChange}
          pageCount={pageCount}
          pageIndex={pageIndex}
          pageSize={pageSize}
          totalCount={totalCount}
        />
      </CardContent>
    </Card>
  );
}

"use client";

import { ArrowUpDownIcon, SearchIcon, WalletIcon } from "lucide-react";
import { paymentStatusLabels } from "@/components/mock-payments";
import {
  activeFilterChips,
  type PaymentFilters,
  panelFilterCount,
  SORT_OPTIONS,
  type SortOptionId,
  type SortState,
  STATUS_OPTIONS,
  type StatusFilter,
  sortLabel,
  statusLabel,
  type TypeFilter,
  toSortOptionId,
  typeLabel,
} from "@/components/payment-filters";
import { PaymentFiltersDrawer } from "@/components/payment-filters-drawer";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  InputGroup,
  InputGroupAddon,
  InputGroupInput,
} from "@/components/ui/input-group";
import { TagGroup, TagGroupItem } from "@/components/ui/tag-group";

interface AdminPaymentsToolbarProps {
  filters: PaymentFilters;
  onChange: (patch: Partial<PaymentFilters>) => void;
  onClear: () => void;
  onSortChange: (id: SortOptionId) => void;
  sort: SortState;
}

const TYPES: readonly TypeFilter[] = ["all", "deposit", "cashout"];

/**
 * Search and the three highest-frequency controls inline; the long tail behind
 * a Filters button; everything applied shown as a removable chip underneath.
 *
 * The chips are what make the panel acceptable. A filter you cannot see is a
 * filter you forget you set, and the next question is always "why am I looking
 * at four rows?" — so the applied state stays on the page whether the panel is
 * open or not, and each chip removes only itself.
 *
 * Below `sm` the three dropdowns fold away and the Filters panel carries
 * everything, the same fork the users toolbar uses.
 */
export function AdminPaymentsToolbar({
  filters,
  onChange,
  onClear,
  onSortChange,
  sort,
}: AdminPaymentsToolbarProps) {
  const chips = activeFilterChips(filters);

  // Kong splits status by payment type. That distinction only earns its keep
  // when you want different statuses per type, which the panel can express —
  // so the toolbar offers the common case, one status across both, and says
  // "Mixed" when the panel has been used to separate them.
  const unifiedStatus: StatusFilter | "mixed" =
    filters.cashoutStatus === filters.depositStatus
      ? filters.cashoutStatus
      : "mixed";

  return (
    <div className="flex flex-col gap-3">
      <div className="flex flex-row items-center gap-2 sm:justify-between sm:gap-3">
        <InputGroup className="min-w-0 flex-1 sm:max-w-xs">
          <InputGroupAddon align="inline-start">
            <SearchIcon />
          </InputGroupAddon>
          <InputGroupInput
            aria-label="Search payments by email"
            onChange={(event) => onChange({ email: event.target.value })}
            placeholder="Search email…"
            type="search"
            value={filters.email}
          />
        </InputGroup>

        <div className="flex shrink-0 items-center gap-2">
          <div className="hidden items-center gap-2 sm:flex">
            <DropdownMenu>
              <DropdownMenuTrigger render={<Button variant="outline" />}>
                <WalletIcon />
                {typeLabel(filters.type)}
              </DropdownMenuTrigger>
              <DropdownMenuContent align="end" className="min-w-44">
                <DropdownMenuGroup>
                  <DropdownMenuRadioGroup
                    onValueChange={(value) =>
                      onChange({ type: value as TypeFilter })
                    }
                    value={filters.type}
                  >
                    {TYPES.map((type) => (
                      <DropdownMenuRadioItem key={type} value={type}>
                        {typeLabel(type)}
                      </DropdownMenuRadioItem>
                    ))}
                  </DropdownMenuRadioGroup>
                </DropdownMenuGroup>
              </DropdownMenuContent>
            </DropdownMenu>

            <DropdownMenu>
              <DropdownMenuTrigger render={<Button variant="outline" />}>
                {unifiedStatus === "mixed"
                  ? "Mixed statuses"
                  : statusLabel(unifiedStatus)}
              </DropdownMenuTrigger>
              <DropdownMenuContent align="end" className="min-w-44">
                <DropdownMenuGroup>
                  <DropdownMenuRadioGroup
                    onValueChange={(value) =>
                      onChange({
                        cashoutStatus: value as StatusFilter,
                        depositStatus: value as StatusFilter,
                      })
                    }
                    value={unifiedStatus === "mixed" ? "" : unifiedStatus}
                  >
                    {STATUS_OPTIONS.map((status) => (
                      <DropdownMenuRadioItem key={status} value={status}>
                        {status === "all"
                          ? "All statuses"
                          : paymentStatusLabels[status]}
                      </DropdownMenuRadioItem>
                    ))}
                  </DropdownMenuRadioGroup>
                </DropdownMenuGroup>
              </DropdownMenuContent>
            </DropdownMenu>

            <DropdownMenu>
              <DropdownMenuTrigger render={<Button variant="outline" />}>
                <ArrowUpDownIcon />
                {sortLabel(sort)}
              </DropdownMenuTrigger>
              <DropdownMenuContent align="end" className="min-w-52">
                <DropdownMenuGroup>
                  <DropdownMenuRadioGroup
                    onValueChange={(value) =>
                      onSortChange(value as SortOptionId)
                    }
                    value={toSortOptionId(sort)}
                  >
                    {SORT_OPTIONS.map((option) => (
                      <DropdownMenuRadioItem key={option.id} value={option.id}>
                        {option.label}
                      </DropdownMenuRadioItem>
                    ))}
                  </DropdownMenuRadioGroup>
                </DropdownMenuGroup>
              </DropdownMenuContent>
            </DropdownMenu>
          </div>

          <PaymentFiltersDrawer
            count={panelFilterCount(filters)}
            filters={filters}
            onChange={onChange}
            onClear={onClear}
          />
        </div>
      </div>

      {chips.length > 0 && (
        <div className="flex flex-wrap items-center gap-1.5">
          {/* Held at `value={[]}` so the chip body is inert: TagGroup is a
              toggle group underneath, and an applied filter is not something
              you press — only its X does anything. */}
          <TagGroup
            onRemove={(key) => {
              const chip = chips.find((item) => item.key === key);
              if (chip) {
                onChange(chip.clear);
              }
            }}
            value={[]}
          >
            {chips.map((chip) => (
              <TagGroupItem key={chip.key} value={chip.key}>
                {chip.label}
              </TagGroupItem>
            ))}
          </TagGroup>
          <Button onClick={onClear} size="sm" variant="ghost">
            Clear all
          </Button>
        </div>
      )}
    </div>
  );
}

"use client";

import { Bar, BarChart, CartesianGrid, XAxis, YAxis } from "recharts";
import {
  ChartContainer,
  ChartTooltip,
  ChartTooltipContent,
} from "@/components/chart";
import { formatValue } from "@/components/chart-formatters";
import {
  type AdminMetric,
  SIGNUP_SERIES,
  type SignupPoint,
} from "@/components/mock-admin";
import { SeriesLegend, seriesColor } from "@/components/series-legend";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { StatDelta, StatValue } from "@/components/ui/stat";

interface AdminOverviewProps {
  hidden: ReadonlySet<string>;
  metrics: readonly AdminMetric[];
  onToggle: (key: string) => void;
  reducedMotion: boolean;
  signups: readonly SignupPoint[];
}

export function AdminOverview({
  hidden,
  metrics,
  onToggle,
  reducedMotion,
  signups,
}: AdminOverviewProps) {
  const shown = SIGNUP_SERIES.filter((item) => !hidden.has(item.key));

  const config = Object.fromEntries(
    SIGNUP_SERIES.map((item, index) => [
      item.key,
      { color: seriesColor(item, index), label: item.label },
    ])
  );

  return (
    <div className="flex flex-col gap-6">
      <section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4 [&>*]:min-w-0">
        {metrics.map((metric) => (
          <Card key={metric.label} size="sm" variant="outline">
            <CardContent className="flex flex-col gap-1">
              <div className="font-medium text-muted-foreground text-xs">
                {metric.label}
              </div>
              <StatValue>
                {metric.value}
                {metric.delta === null ? null : (
                  <StatDelta direction={metric.direction} value={metric.delta}>
                    {metric.deltaLabel}
                  </StatDelta>
                )}
              </StatValue>
              <div className="text-muted-foreground text-xs">
                {metric.sublabel}
              </div>
            </CardContent>
          </Card>
        ))}
      </section>

      <Card variant="outline">
        <CardHeader>
          {/* Semibold rather than CardTitle's default medium. A dashboard panel
              heading competes with a lot of dense content, so it needs more
              weight than a login card's title does -- but the component stays at
              font-medium, in line with every other *Title part in the library. */}
          <CardTitle className="font-semibold">Signups</CardTitle>
          <CardDescription>
            Trial and paid accounts started each month.
          </CardDescription>
        </CardHeader>
        <CardContent className="flex flex-col gap-3">
          <ChartContainer className="h-[240px] w-full" config={config}>
            <BarChart accessibilityLayer data={[...signups]}>
              <CartesianGrid vertical={false} />
              <XAxis
                axisLine={false}
                dataKey="month"
                tickLine={false}
                tickMargin={8}
              />
              <YAxis
                axisLine={false}
                tickFormatter={(value) => formatValue(value, "number")}
                tickLine={false}
                width="auto"
              />
              <ChartTooltip
                content={
                  <ChartTooltipContent
                    formatter={(value, name) => (
                      <div className="flex flex-1 items-center justify-between gap-3">
                        <span className="text-muted-foreground">
                          {config[name as string]?.label ?? name}
                        </span>
                        <span className="font-medium font-mono tabular-nums">
                          {formatValue(value, "number")}
                        </span>
                      </div>
                    )}
                  />
                }
                cursor={false}
              />
              {shown.map((item, index) => (
                <Bar
                  dataKey={item.key}
                  fill={`var(--color-${item.key})`}
                  isAnimationActive={!reducedMotion}
                  key={item.key}
                  // Cap measured against the VISIBLE bands, so hiding the top
                  // series does not leave the stack uncapped.
                  radius={
                    index === shown.length - 1
                      ? ([4, 4, 0, 0] as [number, number, number, number])
                      : 0
                  }
                  stackId="signups"
                  // Matches the panel's real background: `variant="outline"`
                  // has no fill, so a --card seam would be visibly wrong.
                  stroke="var(--background)"
                  strokeWidth={2}
                />
              ))}
            </BarChart>
          </ChartContainer>
          <SeriesLegend
            hidden={hidden}
            onToggle={onToggle}
            series={SIGNUP_SERIES}
          />
        </CardContent>
      </Card>
    </div>
  );
}

"use client";

import { useMemo, useState } from "react";
import {
  fromSortOptionId,
  type RoleFilter,
  type SortOptionId,
  type SortState,
  type StatusFilter,
  type UserSortKey,
} from "@/components/admin-filters";
import { AdminOverview } from "@/components/admin-overview";
import { AdminPaymentsTable } from "@/components/admin-payments-table";
import { type AdminSection, AdminSidebar } from "@/components/admin-sidebar";
import { AdminTopbar } from "@/components/admin-topbar";
import { AdminUserDetail } from "@/components/admin-user-detail";
import { AdminUsersTable } from "@/components/admin-users-table";
import { adminMetrics, signupsByMonth, users } from "@/components/mock-admin";
import { payments } from "@/components/mock-payments";
import {
  DEFAULT_SORT as DEFAULT_PAYMENT_SORT,
  EMPTY_FILTERS,
  matchesPaymentFilters,
  type PaymentFilters,
  type SortState as PaymentSortState,
  fromSortOptionId as paymentSortFromId,
  sortPayments,
} from "@/components/payment-filters";
import { SidebarInset, SidebarProvider } from "@/components/ui/sidebar";
import { useReducedMotion } from "@/components/use-reduced-motion";

/** All state lives here; the panels below are presentational. */
export function AdminPage() {
  const reducedMotion = useReducedMotion();

  const [section, setSection] = useState<AdminSection>("overview");
  const [openUserId, setOpenUserId] = useState<string | null>(null);
  const [search, setSearch] = useState("");
  const [roleFilter, setRoleFilter] = useState<RoleFilter>("all");
  const [statusFilter, setStatusFilter] = useState<StatusFilter>("all");
  const [hidden, setHidden] = useState<ReadonlySet<string>>(new Set());
  const [selected, setSelected] = useState<ReadonlySet<string>>(new Set());
  const [sort, setSort] = useState<SortState | null>({
    direction: "asc",
    key: "name",
  });
  const [pageIndex, setPageIndex] = useState(0);
  const [pageSize, setPageSize] = useState(5);

  const [paymentFilters, setPaymentFilters] =
    useState<PaymentFilters>(EMPTY_FILTERS);
  const [paymentSort, setPaymentSort] =
    useState<PaymentSortState>(DEFAULT_PAYMENT_SORT);
  const [paymentPageIndex, setPaymentPageIndex] = useState(0);
  const [paymentPageSize, setPaymentPageSize] = useState(10);

  const filtered = useMemo(() => {
    const query = search.trim().toLowerCase();
    return users.filter((user) => {
      if (roleFilter !== "all" && user.role !== roleFilter) {
        return false;
      }
      if (statusFilter !== "all" && user.status !== statusFilter) {
        return false;
      }
      if (!query) {
        return true;
      }
      return (
        user.name.toLowerCase().includes(query) ||
        user.email.toLowerCase().includes(query)
      );
    });
  }, [roleFilter, search, statusFilter]);

  const sorted = useMemo(() => {
    if (!sort) {
      return filtered;
    }
    const factor = sort.direction === "asc" ? 1 : -1;
    return [...filtered].sort((a, b) => {
      const left = a[sort.key];
      const right = b[sort.key];
      if (typeof left === "string" && typeof right === "string") {
        return left.localeCompare(right) * factor;
      }
      return ((left as number) - (right as number)) * factor;
    });
  }, [filtered, sort]);

  const openUser = openUserId
    ? (users.find((user) => user.id === openUserId) ?? null)
    : null;

  // `invitedBy` holds the inviter's id, so the record can link to them.
  const inviter = openUser?.invitedBy
    ? (users.find((user) => user.id === openUser.invitedBy) ?? null)
    : null;

  const visiblePayments = useMemo(
    () =>
      sortPayments(
        payments.filter((payment) =>
          matchesPaymentFilters(payment, paymentFilters)
        ),
        paymentSort
      ),
    [paymentFilters, paymentSort]
  );

  const paymentPageCount = Math.max(
    1,
    Math.ceil(visiblePayments.length / paymentPageSize)
  );
  const paymentRows = visiblePayments.slice(
    paymentPageIndex * paymentPageSize,
    paymentPageIndex * paymentPageSize + paymentPageSize
  );

  // Any filter change can shrink the result below the current page.
  const patchPaymentFilters = (patch: Partial<PaymentFilters>) => {
    setPaymentFilters((current) => ({ ...current, ...patch }));
    setPaymentPageIndex(0);
  };

  const pageCount = Math.max(1, Math.ceil(sorted.length / pageSize));
  const pageRows = sorted.slice(
    pageIndex * pageSize,
    pageIndex * pageSize + pageSize
  );

  const toggleSeries = (key: string) => {
    setHidden((current) => {
      const next = new Set(current);
      if (next.has(key)) {
        next.delete(key);
      } else {
        next.add(key);
      }
      return next;
    });
  };

  const toggleRow = (id: string) => {
    setSelected((current) => {
      const next = new Set(current);
      if (next.has(id)) {
        next.delete(id);
      } else {
        next.add(id);
      }
      return next;
    });
  };

  const toggleAllOnPage = (checked: boolean) => {
    setSelected((current) => {
      const next = new Set(current);
      for (const row of pageRows) {
        if (checked) {
          next.add(row.id);
        } else {
          next.delete(row.id);
        }
      }
      return next;
    });
  };

  const filterAndReset =
    <T,>(set: (value: T) => void) =>
    (value: T) => {
      set(value);
      // Page 2 of the unfiltered list usually does not exist once a filter is
      // applied, and a table showing "Page 2 of 1" with no rows looks broken.
      setPageIndex(0);
    };

  // The toolbar and the drawer set the sort directly; the headers cycle it.
  // Both land on the one `sort` state, so the two stay in step with no syncing.
  const setSortFromOption = (id: SortOptionId) => {
    setPageIndex(0);
    setSort(fromSortOptionId(id));
  };

  const cycleSort = (key: UserSortKey) => {
    setPageIndex(0);
    setSort((current) => {
      if (current?.key !== key) {
        return { direction: "asc", key };
      }
      if (current.direction === "asc") {
        return { direction: "desc", key };
      }
      return null;
    });
  };

  return (
    <SidebarProvider>
      <AdminSidebar
        onSectionChange={(next) => {
          setSection(next);
          setOpenUserId(null);
        }}
        section={section}
      />
      {/* min-w-0 is required, not cosmetic. Without it a wide table pushes the
          inset open and the whole document gains a horizontal scrollbar — in
          the app this pattern came from, its absence cost +256px of overflow
          across eight pages. Keystone can bake this into components it owns;
          this one is shadcn's, so it lands at the call site. */}
      <SidebarInset className="min-w-0">
        <AdminTopbar
          detail={openUser?.name}
          onDetailExit={() => setOpenUserId(null)}
          section={section}
        />

        <div className="flex min-w-0 flex-1 flex-col gap-6 p-4 md:p-6">
          {section === "users" && openUser ? (
            <AdminUserDetail
              inviter={inviter}
              onBack={() => setOpenUserId(null)}
              onOpenUser={setOpenUserId}
              user={openUser}
            />
          ) : null}

          {section === "users" && !openUser ? (
            <AdminUsersTable
              onClearSelection={() => setSelected(new Set())}
              onPageIndexChange={setPageIndex}
              onPageSizeChange={(size) => {
                setPageSize(size);
                // Page 3 of a 5-per-page list does not exist at 50 per page.
                setPageIndex(0);
              }}
              onRoleFilterChange={filterAndReset(setRoleFilter)}
              onSearchChange={filterAndReset(setSearch)}
              onOpenUser={setOpenUserId}
              onSort={cycleSort}
              onSortChange={setSortFromOption}
              onStatusFilterChange={filterAndReset(setStatusFilter)}
              onToggleAll={toggleAllOnPage}
              onToggleRow={toggleRow}
              pageCount={pageCount}
              pageIndex={pageIndex}
              pageSize={pageSize}
              roleFilter={roleFilter}
              rows={pageRows}
              search={search}
              selected={selected}
              sort={sort}
              statusFilter={statusFilter}
              totalCount={sorted.length}
            />
          ) : null}

          {section === "overview" ? (
            <AdminOverview
              hidden={hidden}
              metrics={adminMetrics}
              onToggle={toggleSeries}
              reducedMotion={reducedMotion}
              signups={signupsByMonth}
            />
          ) : null}

          {section === "payments" ? (
            <AdminPaymentsTable
              filters={paymentFilters}
              onFiltersChange={patchPaymentFilters}
              onFiltersClear={() => {
                setPaymentFilters(EMPTY_FILTERS);
                setPaymentPageIndex(0);
              }}
              onOpenPayment={() => {
                // Deliberately inert: the record view this would open is the
                // users one, and a payment record is its own piece of work.
              }}
              onPageIndexChange={setPaymentPageIndex}
              onPageSizeChange={(size) => {
                setPaymentPageSize(size);
                setPaymentPageIndex(0);
              }}
              onSortChange={(id) => {
                setPaymentSort(paymentSortFromId(id));
                setPaymentPageIndex(0);
              }}
              pageCount={paymentPageCount}
              pageIndex={paymentPageIndex}
              pageSize={paymentPageSize}
              rows={paymentRows}
              sort={paymentSort}
              totalCount={visiblePayments.length}
            />
          ) : null}

          {section === "billing" || section === "settings" ? (
            <div className="flex h-[420px] items-center justify-center rounded-xl border border-border border-dashed bg-muted/20 text-muted-foreground text-sm">
              {section === "billing" ? "Billing" : "Settings"} lives here.
            </div>
          ) : null}
        </div>
      </SidebarInset>
    </SidebarProvider>
  );
}

